import sys, json

def truncate(s, n=300):
    s = s.replace("\n", " \\n ")
    return s if len(s) <= n else s[:n] + f"...[{len(s)}chars]"

def summarize_content(content):
    if isinstance(content, str):
        return truncate(content)
    out = []
    if isinstance(content, list):
        for c in content:
            if not isinstance(c, dict):
                out.append(truncate(str(c)))
                continue
            t = c.get("type")
            if t == "text":
                out.append("TEXT: " + truncate(c.get("text", "")))
            elif t == "tool_use":
                out.append(f"TOOL_USE[{c.get('name')}]: " + truncate(json.dumps(c.get("input", {}))))
            elif t == "tool_result":
                cont = c.get("content")
                if isinstance(cont, list):
                    txt = " ".join(x.get("text","") for x in cont if isinstance(x, dict))
                else:
                    txt = str(cont)
                out.append("TOOL_RESULT: " + truncate(txt))
            elif t == "thinking":
                out.append("THINKING: " + truncate(c.get("thinking","")))
            else:
                out.append(f"{t}: " + truncate(json.dumps(c)))
    return " | ".join(out)

path = sys.argv[1]
with open(path) as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        try:
            d = json.loads(line)
        except Exception:
            continue
        typ = d.get("type")
        ts = d.get("timestamp", "")
        if typ == "queue-operation":
            print(f"[{ts}] QUEUE-{d.get('operation')}: {truncate(d.get('content',''),400)}")
            continue
        if typ in ("user", "assistant"):
            msg = d.get("message", {})
            role = msg.get("role", typ)
            content = msg.get("content")
            summary = summarize_content(content)
            if summary.strip():
                print(f"[{ts}] {role.upper()}: {summary}")
            continue
        if d.get("attachment", {}).get("type") == "hook_success":
            continue
        # skip other noise types

